import sympy
from sympy import Poly, gcd, S
from functools import reduce

x = sympy.Symbol('x')
Complexes = S.Complexes

CONDITION_LABELS = [
    "H_1: F is an algebraically closed field",
    "¬Q: M is not generated by a linear polynomial x - a"
]

N_HYP = 1
NEG_Q_INDEX = 1

def conditions(witness):
    try:
        if isinstance(witness, tuple) and len(witness) == 2:
            F, M = witness
        else:
            F, M = S.Complexes, witness
    except Exception:
        F, M = S.Complexes, witness

    h1_ok = False
    try:
        if F in (S.Complexes, 'CC', 'C', 'algebraically closed', 'algebraically closed field'):
            h1_ok = True
    except Exception:
        pass

    neg_q_ok = False
    try:
        if hasattr(M, 'gens'):
            gens = list(M.gens)
            if not gens:
                gen = sympy.Integer(0)
            else:
                gen = reduce(gcd, gens)
        elif isinstance(M, (list, tuple, set)):
            M_list = list(M)
            if not M_list:
                gen = sympy.Integer(0)
            else:
                gen = reduce(gcd, M_list)
        else:
            gen = M
        
        if hasattr(gen, 'as_expr'):
            gen = gen.as_expr()
            
        gen = sympy.sympify(gen)
        symbols = gen.free_symbols
        
        if len(symbols) == 1:
            var = list(symbols)[0]
        elif len(symbols) == 0:
            var = sympy.Symbol('x')
        else:
            var = sympy.Symbol('x')
            
        p = Poly(gen, var)
        deg = p.degree()
        
        if deg != 1:
            neg_q_ok = True
    except Exception:
        pass

    return [h1_ok, neg_q_ok]